CREATE TABLE developers(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,password_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE developer_sessions(id TEXT PRIMARY KEY,developer_id TEXT NOT NULL REFERENCES developers(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,csrf_hash TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX sessions_developer ON developer_sessions(developer_id,expires_at);
CREATE TABLE projects(id TEXT PRIMARY KEY,developer_id TEXT NOT NULL REFERENCES developers(id),name TEXT NOT NULL,merchant_name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',payment_ttl INTEGER NOT NULL CHECK(payment_ttl BETWEEN 60 AND 86400),webhook_max_attempts INTEGER NOT NULL CHECK(webhook_max_attempts BETWEEN 1 AND 12),created_at INTEGER NOT NULL);
CREATE INDEX projects_owner ON projects(developer_id);
CREATE TABLE api_keys(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,prefix TEXT NOT NULL,key_hash TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL,last_used_at INTEGER,revoked_at INTEGER);
CREATE INDEX api_keys_project ON api_keys(project_id,created_at);
CREATE TABLE webhook_signing_keys(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,prefix TEXT NOT NULL,cipher BLOB NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),created_at INTEGER NOT NULL,valid_until INTEGER,revoked_at INTEGER);
CREATE UNIQUE INDEX one_active_signing_key ON webhook_signing_keys(project_id) WHERE active=1 AND revoked_at IS NULL;
CREATE TABLE webhook_endpoints(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,url TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),events TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX endpoints_project ON webhook_endpoints(project_id);
CREATE TABLE transactions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),order_no TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('LINK','QR')),bank TEXT NOT NULL CHECK(bank IN('JDB','LDB','IB','BCEL','STB')),merchant_name TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL CHECK(currency='LAK'),description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('WAITING','PAYMENT_COMPLETED','FAILED','EXPIRED','CANCELED')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,completed_at INTEGER,receipt_ref TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,token_cipher BLOB NOT NULL,tag1 TEXT NOT NULL DEFAULT '',tag2 TEXT NOT NULL DEFAULT '',tag3 TEXT NOT NULL DEFAULT '',UNIQUE(project_id,order_no),CHECK((status='PAYMENT_COMPLETED' AND completed_at IS NOT NULL) OR (status!='PAYMENT_COMPLETED' AND completed_at IS NULL)));
CREATE INDEX transactions_project ON transactions(project_id,created_at DESC);
CREATE INDEX transactions_expiry ON transactions(expires_at) WHERE status='WAITING';
CREATE TRIGGER immutable_terminal_status BEFORE UPDATE OF status ON transactions WHEN OLD.status!='WAITING' AND NEW.status!=OLD.status BEGIN SELECT RAISE(ABORT,'terminal payment is immutable'); END;
CREATE TABLE transaction_events(id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE,status TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(transaction_id,status));
CREATE TABLE webhook_events(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),transaction_id TEXT REFERENCES transactions(id),type TEXT NOT NULL,body BLOB NOT NULL,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX unique_transaction_webhook ON webhook_events(transaction_id,type) WHERE transaction_id IS NOT NULL;
CREATE TABLE webhook_jobs(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES webhook_events(id),endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(id),status TEXT NOT NULL CHECK(status IN('PENDING','DELIVERING','DELIVERED','FAILED','DISABLED')),attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL,next_attempt_at INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(event_id,endpoint_id));
CREATE INDEX webhook_jobs_due ON webhook_jobs(status,next_attempt_at,lease_until);
CREATE TABLE webhook_deliveries(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES webhook_jobs(id),event_id TEXT NOT NULL REFERENCES webhook_events(id),endpoint_id TEXT NOT NULL REFERENCES webhook_endpoints(id),attempt INTEGER NOT NULL,http_status INTEGER NOT NULL,response TEXT NOT NULL,error TEXT NOT NULL,duration_ms INTEGER NOT NULL,created_at INTEGER NOT NULL,UNIQUE(job_id,attempt));
CREATE TABLE api_request_logs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),method TEXT NOT NULL,path TEXT NOT NULL,status INTEGER NOT NULL,duration_ms INTEGER NOT NULL,error TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX logs_project ON api_request_logs(project_id,created_at DESC);
